                </div>
              </div>
            )}

            {/* SCHOOL PROFILE */}
            {activeSection === 'school' && isAdmin && (
              <div className="p-10 space-y-10">
                <div className="flex items-center justify-between border-b pb-8">
                   <div>
                      <h3 className="text-3xl font-black text-gray-900 tracking-tighter uppercase italic leading-none">Institutional Info</h3>
                      <p className="text-[10px] text-gray-400 font-black uppercase mt-3">Global Identity Records</p>
                   </div>
                   <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center shadow-lg border-2 border-white"><Building2 size={32} /></div>
                </div>

                <form onSubmit={handleSaveInstitution} className="grid grid-cols-1 md:grid-cols-2 gap-8">
                   <div className="space-y-2">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Official School Name</label>
                      <input type="text" defaultValue={institution.name} className="w-full p-5 bg-gray-50 border-2 border-gray-100 rounded-3xl font-black uppercase italic outline-none focus:border-blue-500 shadow-inner" />
                   </div>
                   <div className="space-y-2">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">MOE Registration No</label>
                      <input type="text" defaultValue={institution.registrationNumber} className="w-full p-5 bg-gray-50 border-2 border-gray-100 rounded-3xl font-bold font-mono outline-none focus:border-blue-500 shadow-inner" />
                   </div>
                   <div className="md:col-span-2 space-y-2">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">School Motto / Vision</label>
                      <input type="text" defaultValue={institution.motto} className="w-full p-5 bg-gray-50 border-2 border-gray-100 rounded-3xl font-bold italic outline-none focus:border-blue-500 shadow-inner" />
                   </div>

                   <div className="md:col-span-2 pt-6">
                      <button type="submit" disabled={isSaving} className="w-full py-6 bg-gray-900 text-white rounded-[32px] font-black uppercase text-xs tracking-[0.2em] shadow-2xl hover:bg-black transition-all flex items-center justify-center gap-3">
                        {isSaving ? <Loader2 className="animate-spin" /> : <Save size={20} />} Commit Institutional Changes
                      </button>
                   </div>
                </form>
              </div>
            )}

            {/* USER ACCOUNTS */}
            {activeSection === 'users' && isAdmin && (
              <div className="p-10 space-y-10">
                <div className="flex items-center justify-between border-b pb-8">
                   <div>
                      <h3 className="text-3xl font-black text-gray-900 tracking-tighter uppercase italic leading-none">Administrative Access</h3>
                      <p className="text-[10px] text-gray-400 font-black uppercase mt-3">Personnel Authorization</p>
                   </div>
                   <button onClick={() => setIsUserModalOpen(true)} className="flex items-center gap-3 bg-blue-600 text-white px-8 py-4 rounded-[24px] font-black uppercase text-[10px] tracking-widest shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all border-b-4 border-blue-800">
                     <UserPlus size={16} /> Enroll User
                   </button>
                </div>

                <div className="overflow-x-auto">
                   <table className="w-full text-left">
                      <thead>
                         <tr className="text-[10px] font-black text-gray-300 uppercase tracking-[0.3em] border-b pb-4">
                            <th className="pb-6">User Profile</th>
                            <th className="pb-6">Functional Role</th>
                            <th className="pb-6">Status</th>
                            <th className="pb-6 text-right">Actions</th>
                         </tr>
                      </thead>
                      <tbody className="divide-y-2 divide-gray-50">
                         {users.map(u => (
                           <tr key={u.id} className="group hover:bg-gray-50/50 transition-colors">
                              <td className="py-6">
                                 <div className="flex items-center gap-4">
                                    <div className="w-12 h-12 bg-gray-100 rounded-xl overflow-hidden border-2 border-white shadow-sm"><img src={u.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${u.name}`} alt="" /></div>
                                    <div>
                                       <p className="font-black text-gray-900 uppercase italic leading-none">{u.name}</p>
                                       <p className="text-[10px] text-gray-400 font-bold mt-1 uppercase">{u.email}</p>
                                    </div>
                                 </div>
                              </td>
                              <td className="py-6">
                                 <span className="px-3 py-1 bg-blue-50 text-blue-600 text-[9px] font-black uppercase tracking-widest rounded-lg border border-blue-100 shadow-sm">{u.role}</span>
                              </td>
                              <td className="py-6">
                                 <div className="flex items-center gap-2"><div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div> <span className="text-[9px] font-black text-gray-400 uppercase">ACTIVE</span></div>
                              </td>
                              <td className="py-6 text-right">
                                 <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                    <button className="p-3 bg-white text-gray-400 hover:text-blue-600 rounded-xl shadow-sm border border-gray-100"><Edit3 size={14} /></button>
                                    <button className="p-3 bg-white text-gray-400 hover:text-red-600 rounded-xl shadow-sm border border-gray-100"><Trash2 size={14} /></button>
                                 </div>
                              </td>
                           </tr>
                         ))}
                      </tbody>
                   </table>
                </div>
              </div>
            )}

            {/* AUDIT LOGS */}
            {activeSection === 'logs' && isAdmin && (
              <div className="p-10 space-y-8">
                <div className="flex items-center justify-between border-b pb-8">
                  <div>
                    <h3 className="text-3xl font-black text-gray-900 tracking-tighter uppercase italic leading-none">Security Logs</h3>
                    <p className="text-[10px] text-gray-400 font-black uppercase mt-3">Institutional Activity Feed</p>
                  </div>
                  <button onClick={fetchAuditLogs} className="p-4 bg-gray-50 text-blue-600 hover:bg-blue-100 rounded-2xl transition-all shadow-sm">
                    <RefreshCw className={`w-5 h-5 ${isLogsLoading ? 'animate-spin' : ''}`} />
                  </button>
                </div>

                <div className="relative">
                  <Search className="absolute left-5 top-5 w-5 h-5 text-gray-400" />
                  <input type="text" placeholder="Search events by user or action..." value={logSearch} onChange={e => setLogSearch(e.target.value)} className="w-full pl-14 pr-4 py-5 bg-gray-50 border-2 border-gray-100 rounded-[32px] outline-none focus:border-blue-500 font-bold shadow-inner" />
                </div>

                <div className="overflow-x-auto rounded-[32px] border-2 border-gray-50 overflow-hidden shadow-xl">
                  <table className="w-full text-left">
                    <thead className="bg-gray-900 text-[10px] font-black uppercase tracking-[0.2em] text-gray-400">
                      <tr>
                        <th className="px-8 py-6">Timeline</th>
                        <th className="px-8 py-6">Actor</th>
                        <th className="px-8 py-6">Device Origin</th>
                        <th className="px-8 py-6">Event</th>
                        <th className="px-8 py-6 text-right">Details</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y-2 divide-gray-50 text-xs">
                      {filteredLogs.map(log => (
                        <tr key={log.id} className="hover:bg-gray-50 transition-colors group">
                          <td className="px-8 py-6 text-gray-500 font-mono text-[10px]">
                            {new Date(log.createdAt).toLocaleString('en-KE', { hour12: true, hour: '2-digit', minute: '2-digit', day: '2-digit', month: 'short' })}
                          </td>
                          <td className="px-8 py-6 font-black text-gray-900 uppercase italic tracking-tighter">{log.userName}</td>
                          <td className="px-8 py-6">
                            <div className="flex flex-col gap-1">
                               <div className="flex items-center gap-2 text-[9px] font-black text-gray-400 uppercase tracking-widest">
                                  <Monitor size={10} className="text-blue-400" /> {log.userAgent?.includes('Mobile') ? 'Mobile' : 'Workstation'}
                               </div>
                               <div className="flex items-center gap-2 text-[9px] font-bold text-gray-300">
                                  <Globe size={10} /> {log.ipAddress || 'Internal Network'}
                               </div>
                            </div>
                          </td>
                          <td className="px-8 py-6">
                            <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest shadow-sm ${
                              log.action === 'DELETE' ? 'bg-red-50 text-red-600 border border-red-100' :
                              log.action === 'UPDATE' ? 'bg-amber-50 text-amber-600 border border-amber-100' :
                              log.action === 'LOGIN' ? 'bg-blue-900 text-white' :
                              'bg-green-50 text-green-600 border border-green-100'
                            }`}>
                              {log.action}
                            </span>
                          </td>
                          <td className="px-8 py-6 text-right">
                             <button onClick={() => alert(JSON.stringify(log, null, 2))} className="p-3 bg-white text-gray-400 hover:text-blue-600 rounded-xl shadow-sm border border-gray-100 transition-all">
                               <Eye size={16} />
                             </button>
                          </td>
                        </tr>
                      ))}
                      {filteredLogs.length === 0 && (
                        <tr>
                           <td colSpan={5} className="py-32 text-center text-gray-300 font-black uppercase tracking-[0.4em] italic">No security events found.</td>
                        </tr>
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* SECURITY (PASSWORD) */}
            {activeSection === 'security' && (
              <div className="p-10 space-y-10">
                <div className="flex items-center gap-6 border-b pb-8">
                   <div className="p-6 bg-gray-900 text-white rounded-[24px] shadow-2xl"><LockKeyhole size={32} /></div>
                   <div>
                      <h3 className="text-3xl font-black text-gray-900 tracking-tighter uppercase italic leading-none">Authentication Keys</h3>
                      <p className="text-[10px] text-gray-400 font-black uppercase mt-3">Rotate Institutional Credentials</p>
                   </div>
                </div>

                <form onSubmit={handlePasswordChange} className="max-w-xl space-y-8">
                   {pwError && (
                     <div className="p-6 bg-red-50 text-red-600 rounded-[32px] border-2 border-red-100 flex items-center gap-4 animate-pulse">
                        <ShieldAlert size={24} />
                        <p className="text-xs font-black uppercase tracking-widest">{pwError}</p>
                     </div>
                   )}
                   {pwSuccess && (
                     <div className="p-6 bg-green-50 text-green-700 rounded-[32px] border-2 border-green-100 flex items-center gap-4">
                        <CheckCircle2 size={24} />
                        <p className="text-xs font-black uppercase tracking-widest">{pwSuccess}</p>
                     </div>
                   )}

                   <div className="space-y-4">
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Current Password Entry</label>
                        <input required type="password" value={pwForm.current} onChange={e => setPwForm({...pwForm, current: e.target.value})} placeholder="••••••••" className="w-full p-6 bg-gray-50 border-2 border-gray-100 rounded-[32px] outline-none focus:border-blue-500 font-bold shadow-inner" />
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="space-y-2">
                          <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">New Key</label>
                          <input required type="password" value={pwForm.new} onChange={e => setPwForm({...pwForm, new: e.target.value})} placeholder="Min 6 chars" className="w-full p-6 bg-gray-50 border-2 border-gray-100 rounded-[32px] outline-none focus:border-blue-500 font-bold shadow-inner" />
                        </div>
                        <div className="space-y-2">
                          <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Verify Key</label>
                          <input required type="password" value={pwForm.confirm} onChange={e => setPwForm({...pwForm, confirm: e.target.value})} placeholder="Repeat key" className="w-full p-6 bg-gray-50 border-2 border-gray-100 rounded-[32px] outline-none focus:border-blue-500 font-bold shadow-inner" />
                        </div>
                      </div>
                   </div>

                   <button type="submit" disabled={isSaving} className="w-full py-6 bg-gray-900 text-white rounded-[32px] font-black uppercase text-xs tracking-[0.2em] shadow-2xl hover:bg-black transition-all active:scale-95 flex items-center justify-center gap-4 border-b-8 border-black">
                     {isSaving ? <Loader2 className="animate-spin" /> : <ShieldCheck size={24} />}
                     Update Security Credentials
                   </button>
                </form>

                <div className="p-10 bg-blue-50/50 rounded-[40px] border-2 border-blue-100 relative overflow-hidden group">
                   <div className="absolute top-0 right-0 p-8 opacity-5 group-hover:scale-110 transition-transform duration-1000"><Monitor size={120} /></div>
                   <h4 className="text-[10px] font-black text-blue-900 uppercase tracking-widest mb-4 flex items-center gap-2">
                     <History size={14} /> Global Sync Protocol
                   </h4>
                   <p className="text-xs font-bold text-blue-800 italic leading-relaxed max-w-lg">
                     A security handshake will be sent across the ElimuSmart Cloud. Updating your password here will invalidate active sessions on other devices for security. You will need to re-authenticate on your mobile phone or tablet using the new keys.
                   </p>
                </div>
              </div>
            )}

            {/* Other sections (Roles, etc.) would follow similar layout... */}
          </div>
        </div>
      </div>
    </div>
  );
};

const NavItem: React.FC<{ icon: any, label: string, active: boolean, onClick: () => void }> = ({ icon: Icon, label, active, onClick }) => (
  <button 
    onClick={onClick}
    className={`w-full flex items-center gap-5 px-8 py-5 rounded-[24px] text-[11px] font-black uppercase tracking-widest transition-all ${active ? 'bg-blue-600 text-white shadow-2xl shadow-blue-200 border-b-4 border-blue-800' : 'text-gray-400 hover:bg-gray-50 hover:text-gray-900'}`}
  >
    <Icon className={`w-6 h-6 ${active ? 'text-white' : 'text-gray-300'}`} />
    <span>{label}</span>
  </button>
);

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  Settings as SettingsIcon, 
  School, 
  Calendar, 
  Shield, 
  Bell, 
  User, 
  Save, 
  Loader2, 
  Database,
  History,
  Lock,
  Upload,
  Camera,
  Trash2,
  Users,
  Plus,
  Key,
  Smartphone,
  Banknote,
  CreditCard,
  Hash,
  Edit3,
  X,
  ShieldCheck,
  UserPlus,
  RefreshCw,
  Clock as ClockIcon,
  ShieldAlert,
  ArrowRight,
  ClipboardList,
  Search,
  Eye,
  Monitor,
  Globe,
  MapPin,
  LockKeyhole,
  CheckCircle2,
  Mail,
  Building2,
  Fingerprint,
  ImagePlus,
  ShieldQuestion
} from 'lucide-react';
import { UserRole, User as UserType, CustomRole, AuditLog } from '../types';
import { apiService } from '../services/apiService';

interface SettingsModuleProps {
  currentUser: UserType;
  users: UserType[];
  setUsers: React.Dispatch<React.SetStateAction<UserType[]>>;
  schoolLogo: string | null;
  setSchoolLogo: (logo: string | null) => void;
  schoolConfig: any;
  setSchoolConfig: React.Dispatch<React.SetStateAction<any>>;
  systemRoles: CustomRole[];
  setSystemRoles: React.Dispatch<React.SetStateAction<CustomRole[]>>;
  isBackendLive?: boolean;
}

export const SettingsModule: React.FC<SettingsModuleProps> = ({ 
  currentUser, 
  users, 
  setUsers, 
  schoolLogo, 
  setSchoolLogo,
  schoolConfig,
  setSchoolConfig,
  systemRoles,
  setSystemRoles,
  isBackendLive = false
}) => {
  const [activeSection, setActiveSection] = useState<'profile' | 'school' | 'users' | 'roles' | 'logs' | 'security'>('profile');
  const [isSaving, setIsSaving] = useState(false);
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]);
  const [isLogsLoading, setIsLogsLoading] = useState(false);
  const [logSearch, setLogSearch] = useState('');
  const logoInputRef = useRef<HTMLInputElement>(null);

  // Password Change States
  const [pwForm, setPwForm] = useState({ current: '', new: '', confirm: '' });
  const [pwError, setPwError] = useState('');
  const [pwSuccess, setPwSuccess] = useState('');

  // User Management States
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<UserType | null>(null);
  const [userFormData, setUserFormData] = useState({ name: '', email: '', role: UserRole.SUBJECT_TEACHER, password: '' });

  // Role Management States
  const [isRoleModalOpen, setIsRoleModalOpen] = useState(false);
  const [editingRole, setEditingRole] = useState<CustomRole | null>(null);
  const [roleFormData, setRoleFormData] = useState({ name: '', description: '', baseRole: UserRole.SUBJECT_TEACHER });

  const institution = (currentUser as any).institution || { name: schoolConfig.schoolName, motto: schoolConfig.motto, registrationNumber: schoolConfig.registrationNo };

  useEffect(() => {
    if (activeSection === 'logs' && isBackendLive) fetchAuditLogs();
    // In demo mode or live mode, we might want to fetch users
    if (activeSection === 'users' && isBackendLive) fetchUsers();
  }, [activeSection, isBackendLive]);

  const fetchAuditLogs = async () => {
    setIsLogsLoading(true);
    try {
      const data = await apiService.request('/admin/logs');
      setAuditLogs(data);
    } catch (e) {
      console.error("Failed to fetch logs");
    } finally {
      setIsLogsLoading(false);
    }
  };

  const fetchUsers = async () => {
    try {
      const data = await apiService.request('/users');
      setUsers(data);
    } catch (e) {
      console.error("Failed to fetch users");
    }
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        setSchoolLogo(base64String);
        triggerSyncNotice("Institutional Branding Updated");
      };
      reader.readAsDataURL(file);
    }
  };

  const triggerSyncNotice = (msg: string) => {
    alert(msg + ". Changes will be reflected on all receipts and reports immediately.");
  };

  const handlePasswordChange = async (e: React.FormEvent) => {
    e.preventDefault();
    setPwError('');
    setPwSuccess('');

    if (pwForm.new !== pwForm.confirm) {
      setPwError('New passwords do not match.');
      return;
    }
    if (pwForm.new.length < 6) {
      setPwError('Password must be at least 6 characters.');
      return;
    }

    setIsSaving(true);
    try {
      if (isBackendLive) {
        await apiService.request('/auth/change-password', {
          method: 'PUT',
          body: JSON.stringify({
            currentPassword: pwForm.current,
            newPassword: pwForm.new
          })
        });
      } else {
        await new Promise(resolve => setTimeout(resolve, 1000));
      }
      setPwSuccess('Credentials updated successfully. Security tokens refreshed.');
      setPwForm({ current: '', new: '', confirm: '' });
    } catch (err: any) {
      setPwError(err.message || 'Failed to update password. Verify current credentials.');
    } finally {
      setIsSaving(false);
    }
  };

  const handleSaveRole = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingRole) {
      setSystemRoles(prev => prev.map(r => r.id === editingRole.id ? { ...r, ...roleFormData } : r));
    } else {
      const newRole: CustomRole = {
        id: 'role-' + Date.now(),
        ...roleFormData,
        isSystemRole: false
      };
      setSystemRoles(prev => [...prev, newRole]);
    }
    setIsRoleModalOpen(false);
    setEditingRole(null);
  };

  const filteredLogs = useMemo(() => {
    return auditLogs.filter(log => 
      log.userName.toLowerCase().includes(logSearch.toLowerCase()) ||
      log.resource.toLowerCase().includes(logSearch.toLowerCase()) ||
      log.action.toLowerCase().includes(logSearch.toLowerCase())
    );
  }, [auditLogs, logSearch]);

  const isAdmin = currentUser.role === UserRole.ADMIN;

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-black text-gray-900 tracking-tighter uppercase italic leading-none">System Core</h1>
          <p className="text-gray-400 font-bold uppercase text-[10px] tracking-[0.3em] mt-3 flex items-center gap-3">
             <span className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></span>
             {schoolConfig.schoolName} • Administration
          </p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
        <div className="md:col-span-1 space-y-2">
          <nav className="bg-white rounded-[32px] border-2 border-gray-50 p-3 shadow-xl space-y-1">
            <NavItem icon={User} label="My Identity" active={activeSection === 'profile'} onClick={() => setActiveSection('profile')} />
            {isAdmin && (
              <>
                <NavItem icon={School} label="School Profile" active={activeSection === 'school'} onClick={() => setActiveSection('school')} />
                <NavItem icon={Users} label="User Accounts" active={activeSection === 'users'} onClick={() => setActiveSection('users')} />
                <NavItem icon={Shield} label="Role Definitions" active={activeSection === 'roles'} onClick={() => setActiveSection('roles')} />
                <NavItem icon={ClipboardList} label="Audit Trail" active={activeSection === 'logs'} onClick={() => setActiveSection('logs')} />
              </>
            )}
            <NavItem icon={Lock} label="Access Keys" active={activeSection === 'security'} onClick={() => setActiveSection('security')} />
          </nav>
        </div>

        <div className="md:col-span-3">
          <div className="bg-white rounded-[48px] border-2 border-gray-50 shadow-2xl overflow-hidden min-h-[600px] animate-in slide-in-from-bottom-4 duration-500">

            {/* SCHOOL PROFILE & LOGO UPLOAD */}
            {activeSection === 'school' && isAdmin && (
              <div className="p-10 space-y-12">
                <div className="flex items-center justify-between border-b pb-8">
                   <div>
                      <h3 className="text-3xl font-black text-gray-900 tracking-tighter uppercase italic leading-none">Institutional Identity</h3>
                      <p className="text-[10px] text-gray-400 font-black uppercase mt-3">Visual Branding & Legal Metadata</p>
                   </div>
                   <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center shadow-lg border-2 border-white"><Building2 size={32} /></div>
                </div>

                <div className="flex flex-col md:flex-row items-start gap-10">
                   <div className="space-y-4">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Official School Logo</label>
                      <div className="relative group">
                         <div className="w-48 h-48 bg-gray-50 rounded-[40px] border-4 border-dashed border-gray-200 flex items-center justify-center overflow-hidden transition-all group-hover:border-blue-500 group-hover:bg-blue-50/30">
                            {schoolLogo ? (
                              <img src={schoolLogo} className="w-full h-full object-cover" alt="School Logo" />
                            ) : (
                              <div className="text-center p-6">
                                <ImagePlus size={40} className="text-gray-300 mx-auto mb-2" />
                                <p className="text-[8px] font-black text-gray-400 uppercase leading-tight">PNG/JPG Preferred</p>
                              </div>
                            )}
                         </div>
                         <button 
                           onClick={() => logoInputRef.current?.click()}
                           className="absolute -bottom-4 -right-4 bg-gray-900 text-white p-5 rounded-[24px] shadow-2xl border-4 border-white hover:bg-black transition-all active:scale-95"
                         >
                           <Camera size={20} />
                         </button>
                         <input type="file" ref={logoInputRef} className="hidden" accept="image/*" onChange={handleLogoUpload} />
                      </div>
                      <p className="text-[9px] text-gray-400 font-bold uppercase italic mt-4 max-w-[200px]">This logo will be visible on all report forms, financial receipts, and the main portal header.</p>
                   </div>

                   <form className="flex-1 grid grid-cols-1 md:grid-cols-2 gap-8" onSubmit={(e) => { e.preventDefault(); alert("Profile metadata synchronized."); }}>
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Official School Name</label>
